import{_ as o,o as t,c as r,a2 as n}from"./chunks/framework.BM5YPQmL.js";const b=JSON.parse('{"title":"3.0.0-WP-runtime-hardening-and-experience-rebase","description":"","frontmatter":{},"headers":[],"relativePath":"release/3.0.0-WP-runtime-hardening-and-experience-rebase.md","filePath":"release/3.0.0-WP-runtime-hardening-and-experience-rebase.md"}'),a={name:"release/3.0.0-WP-runtime-hardening-and-experience-rebase.md"};function c(d,e,i,s,l,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="_3-0-0-wp-runtime-hardening-and-experience-rebase" tabindex="-1">3.0.0-WP-runtime-hardening-and-experience-rebase <a class="header-anchor" href="#_3-0-0-wp-runtime-hardening-and-experience-rebase" aria-label="Permalink to &quot;3.0.0-WP-runtime-hardening-and-experience-rebase&quot;">​</a></h1><p><strong>2026-11-21 · build 479 · SHA256 见下表</strong></p><p>四阶段基建重构包：启动栈重构（OCRMECL）、i18n 与编码体系、应用与前端容错、全量回归发版。任一阶段失败全包不予验收——四阶段全部通过。</p><h2 id="阶段一-启动栈重构-ocrmecl" tabindex="-1">阶段一：启动栈重构（OCRMECL） <a class="header-anchor" href="#阶段一-启动栈重构-ocrmecl" aria-label="Permalink to &quot;阶段一：启动栈重构（OCRMECL）&quot;">​</a></h2><ul><li><strong>OCRMECL（Open Cube Runtime Machine Environment Compatibility Layer）</strong>：物理独立的引导兼容层，在 OCBL 之前于两条固件轨上静默执行。唯一共享契约 <code>interface/boot_handoff.h</code>。</li><li><strong>BIOS 轨</strong>（<code>ocrmecl/bios/</code>，纯汇编）：El Torito 组合镜像 <code>[stage1 512B][core][OCBL.BIN]</code>；core 完成拉平——A20 强开（int15h+0x92 双图案验证）、临时 GDT@0x1000 + 故障存根@0x1100 + 256 门 IDT@0x2000（表位于 0x7C00 以下，搬移后仍存活，关闭历史&quot;继承固件 IVT&quot;窗口）、8259A 重映射+全掩蔽、unreal-mode IOAPIC 全 RTE 掩蔽、PIC EOI/PS2 排空/DMA 掩蔽，随后前向搬移内嵌 OCBL.BIN 至 0x7C00 并按 El Torito 契约移交（DL 透传，OCBL 零改动）。</li><li><strong>UEFI 轨</strong>（<code>ocrmecl/efi/</code>，独立 PE）：执行引导的全部固件调用（连接扫描、整盘 ISO 读入内存、OCBL.EFI 从缓冲 LoadImage、GOP 800x600x32、RSDP、固定窗口预留、看门狗拆除、GetMemoryMap、ExitBootServices 重试纪律），随后重写 GDT/IDT（自有 64 位表 + 诊断停机存根）、CR3 全树剥离 NX/置 RW（WP 临时关闭绕过固件页表自保护），最后按 MS x64 ABI 跳转 OCBL 的 raw 入口。EBS 之后零固件服务调用。</li><li><strong>OCBL UEFI 重构为固件无关</strong>：<code>ocbl_raw.c</code>（EBS 后入口）、<code>ocbl_ramdisk.c</code>（RAM ISO 唯一磁盘后端）、<code>ocbl_con_efi.c</code>（帧缓冲控制台+内嵌 8x16 字形+直接 PIT 时钟+串口键盘）、<code>ocbl_mmap_efi.c</code>（捕获的 EBS 内存图→E820）；旧固件流程五文件删除。</li><li><strong>探测器</strong>（<code>tools/probe/</code>）：BIOS/UEFI 两个裸机探测镜像 + <code>qemu_behaviors.sh</code> 编排，四份原始转储（默认/严格 × BIOS/UEFI）与《QEMU 保姆行为拉平清单》存于 <code>evidence/.../probe/</code>。</li><li><strong>严格矩阵</strong>（<code>make test-strict</code>）：<code>-cpu qemu64,enforce -machine vmport=off -boot strict=on</code> 下双轨全链 OCRMECL→OCBL→内核→ush <strong>双绿</strong>。</li></ul><h2 id="阶段二-i18n-与编码体系" tabindex="-1">阶段二：i18n 与编码体系 <a class="header-anchor" href="#阶段二-i18n-与编码体系" aria-label="Permalink to &quot;阶段二：i18n 与编码体系&quot;">​</a></h2><ul><li><strong>资源表</strong>（<code>ocos/interface/i18n_res.h</code> + <code>ocos/kernel/core_i18n_res.c</code>）：51 条系统消息的 <code>lang_en</code>/<code>lang_zh</code> 表 + <code>get_text(MSG_ID)</code>（zh→en→&quot;?&quot;回退）；追加式扩展协议与构建期尺寸断言。</li><li><strong>L1 通道</strong>：L1SVC op 18（<code>get_text</code>）+ op 19（<code>serial-probe</code>）；<code>ocos/interface/i18n.h</code> 的 L1 助手。</li><li><strong>迁移</strong>：L0 内核/异常/用户态 ELF/更新流程 24 处 + 18 个零翻译 L1 应用 51 键 + ush 高频&quot;未找到命令&quot;；机器契约锚点清单 <code>tools/i18n_contract_anchor.txt</code>（14 条永英文行）。</li><li><strong>启动恢复</strong>：<code>shell.lang</code> 与 <code>serial.encoding</code> 开机读回（旧流程只写不读——中文用户每次重启回英文，勘案发现）。</li><li><strong>serial-probe 向导</strong>：两种编码样例裸发 COM1 由用户肉眼确认后写入 <code>/etc/opencube.conf</code> 并持久化。</li><li><strong>update.json 双语</strong>：<code>description: {en, zh}</code> 新结构（<code>changes</code> 扁平键保留兼容旧内核）；内核 v2 链路与网页端均已适配。</li><li><strong>抽查</strong>：<code>evidence/.../i18n-samples/zh-20-samples.md</code>——中文环境 20 条报错与提示 <strong>100% 中文</strong>。</li></ul><h2 id="阶段三-应用与前端容错" tabindex="-1">阶段三：应用与前端容错 <a class="header-anchor" href="#阶段三-应用与前端容错" aria-label="Permalink to &quot;阶段三：应用与前端容错&quot;">​</a></h2><ul><li><strong>CONFIG_TUI 三态</strong>：<code>n</code>（默认，不编译——L0 服务剔除+9 个 tui* 程序不入注册表）、<code>h</code>（全隐藏+直接调用拦截，双语提示）、<code>y</code>（完整开放）。三态 QEMU 证据存 <code>tui-switch/</code>。</li><li><strong>Update Live 容错</strong>：向导 2/5 步识别 ISO Live 环境（<code>current boot: ISO</code> 且无 A/B 盘），输出中英双语提示优雅退出——不崩溃不卡死。</li><li><strong>官网死链修复</strong>：dev 通道（默认页签！）两按钮从 <code>href=&quot;#&quot;</code> 修复为绝对地址直链；<code>update_website.sh</code> 每次发版自动生成 dev 块（根除&quot;人工维护遗漏&quot;）；<code>tools/verify_download_links.py</code> 无头浏览器断言 <strong>5/5 PASS</strong>。</li></ul><h2 id="阶段四-回归与发版" tabindex="-1">阶段四：回归与发版 <a class="header-anchor" href="#阶段四-回归与发版" aria-label="Permalink to &quot;阶段四：回归与发版&quot;">​</a></h2><p>31/31 + WP-08 门禁 43/43 + dhtest 5/5（含确定性）+ SSH E2E 5/5 + HTTPS E2E 8/8 + 严格矩阵双绿 + verify_presentation 全过（新口径 312 命令/292 列出/223 L1SVC 操作/165,363 行）。</p><h2 id="sha256" tabindex="-1">SHA256 <a class="header-anchor" href="#sha256" aria-label="Permalink to &quot;SHA256&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资产</th><th>SHA256</th></tr></thead><tbody><tr><td>opencube-3.0.0-WP-runtime-hardening-and-experience-rebase.iso</td><td><code>2565f075cef5e31767e7ef03b664b6f9a2f579580a91a4ecf40b10facf2acc89</code></td></tr><tr><td>opencube-3.0.0-WP-runtime-hardening-and-experience-rebase-src.zip</td><td><code>c735f4975f5ad98100cdaf7c4b7f2b80450be56ea777aa96f5d632766422f7b6</code></td></tr><tr><td>opencube-3.0.0-WP-runtime-hardening-and-experience-rebase-update.tar.gz</td><td><code>db0c8b33a67543cd47f77d7b7b0a864445bb8350c1700acf6ebe713fa058095b</code></td></tr></tbody></table><h2 id="已知事项" tabindex="-1">已知事项 <a class="header-anchor" href="#已知事项" aria-label="Permalink to &quot;已知事项&quot;">​</a></h2><ul><li><strong>K-07</strong>：UEFI 轨（OCRMECL post-EBS 架构）不再扫描非引导磁盘——多盘扫描、A/B 槽位启动与外部 loader 链式加载保留为 BIOS 轨能力；UEFI 安装盘引导需后续在 OCRMECL 增加磁盘驱动（后续工作包）。</li><li>K-01/K-02/K-03/K-05/K-06 沿袭不变（见 KNOWN_ISSUES）。</li></ul>',15)])])}const g=o(a,[["render",c]]);export{b as __pageData,g as default};
